class CalibrationMethod:
    """Group-wise Platt scaling with James-Stein shrinkage."""

    def __init__(self):
        self.eps = 1e-6
        self.k_shrink = 50.0  # Shrinkage strength parameter
        self.group_params_ = {}
        self.global_params_ = (1.0, 0.0)

    def _fit_platt(self, probs, labels):
        probs = np.asarray(probs).reshape(-1)
        labels = np.asarray(labels).reshape(-1).astype(int)
        logits = special.logit(np.clip(probs, self.eps, 1.0 - self.eps))

        def objective(params):
            a, b = params
            cal = special.expit(a * logits + b)
            p = np.clip(cal, self.eps, 1.0 - self.eps)
            loss = -(labels * np.log(p) + (1 - labels) * np.log(1 - p))
            return float(np.mean(loss))

        # Constrain a > 0 to preserve ordering (monotonicity)
        result = optimize.minimize(
            objective, 
            x0=[1.0, 0.0], 
            bounds=[(1e-3, 10.0), (-10.0, 10.0)],
            method="L-BFGS-B"
        )
        return result.x if result.success else np.array([1.0, 0.0])

    def fit(self, probs, labels, groups=None):
        probs = np.asarray(probs).reshape(-1)
        labels = np.asarray(labels).reshape(-1).astype(int)

        # Fit global model
        self.global_params_ = self._fit_platt(probs, labels)
        self.group_params_ = {}

        if groups is None:
            return self

        groups = np.asarray(groups).reshape(-1)
        for g in np.unique(groups):
            mask = groups == g
            n_g = int(mask.sum())
            if n_g < 5 or np.unique(labels[mask]).size < 2:
                self.group_params_[int(g)] = self.global_params_
                continue

            local_params = self._fit_platt(probs[mask], labels[mask])
            # James-Stein style shrinkage
            alpha = n_g / (n_g + self.k_shrink)
            g_params = alpha * local_params + (1.0 - alpha) * self.global_params_
            self.group_params_[int(g)] = g_params

        return self

    def predict_proba(self, probs, groups=None):
        probs = np.asarray(probs).reshape(-1)
        logits = special.logit(np.clip(probs, self.eps, 1.0 - self.eps))

        if groups is None:
            a, b = self.global_params_
            return np.clip(special.expit(a * logits + b), self.eps, 1.0 - self.eps)

        groups = np.asarray(groups).reshape(-1)
        out = np.empty_like(probs)
        for g in np.unique(groups):
            mask = groups == g
            a, b = self.group_params_.get(int(g), self.global_params_)
            out[mask] = special.expit(a * logits[mask] + b)

        return np.clip(out, self.eps, 1.0 - self.eps)

