class CalibrationMethod:
    """Group-wise Isotonic Regression with Shrinkage."""

    def __init__(self):
        self.eps = 1e-6
        self.k_shrink = 100.0
        self.global_iso_ = IsotonicRegression(y_min=0.0, y_max=1.0, out_of_bounds="clip")
        self.group_isos_ = {}
        self.group_alphas_ = {}
        self.base_rate_ = 0.5
        self.group_base_rates_ = {}

    def fit(self, probs, labels, groups=None):
        probs = np.asarray(probs).reshape(-1)
        labels = np.asarray(labels).reshape(-1).astype(int)
        self.base_rate_ = float(np.clip(np.mean(labels), 0.05, 0.95))

        self.global_iso_.fit(probs, labels)
        self.group_isos_ = {}
        self.group_alphas_ = {}
        self.group_base_rates_ = {}

        if groups is None:
            return self

        groups = np.asarray(groups).reshape(-1)
        for g in np.unique(groups):
            mask = groups == g
            n_g = int(mask.sum())
            if n_g < 5:
                continue

            self.group_base_rates_[int(g)] = float(np.clip(np.mean(labels[mask]), 0.05, 0.95))

            if n_g < 20 or np.unique(labels[mask]).size < 2:
                continue

            iso_g = IsotonicRegression(y_min=0.0, y_max=1.0, out_of_bounds="clip")
            iso_g.fit(probs[mask], labels[mask])
            self.group_isos_[int(g)] = iso_g

            alpha = n_g / (n_g + self.k_shrink)
            self.group_alphas_[int(g)] = alpha

        return self

    def predict_proba(self, probs, groups=None):
        probs = np.asarray(probs).reshape(-1)

        global_preds = self.global_iso_.predict(probs)

        if groups is None:
            out = global_preds
        else:
            groups = np.asarray(groups).reshape(-1)
            out = np.empty_like(probs)

            for g in np.unique(groups):
                mask = groups == g
                if int(g) in self.group_isos_:
                    iso_g = self.group_isos_[int(g)]
                    alpha = self.group_alphas_[int(g)]
                    g_preds = iso_g.predict(probs[mask])
                    out[mask] = alpha * g_preds + (1.0 - alpha) * global_preds[mask]
                else:
                    out[mask] = global_preds[mask]

        # Tie-breaking for strict monotonicity
        out = out + 1e-5 * probs

        # Subgroup-aware soft smoothing
        if groups is not None:
            for g in np.unique(groups):
                mask = groups == g
                br = self.group_base_rates_.get(int(g), self.base_rate_)
                out[mask] = 0.95 * out[mask] + 0.05 * br
        else:
            out = 0.95 * out + 0.05 * self.base_rate_

        return np.clip(out, self.eps, 1.0 - self.eps)
